//! 📋️ Original vector publication keeps actual backing and finite Source custody.
use semio_framework_value_control_contract::*;
use semio_framework_value_original_vector::OriginalVectorCursor;
use semio_framework_value_retirement::OriginalRetirementFailure;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
fn run<E>(bank:&mut EffectBank,grant:RetainedCloneGrant,work:u64,slot:&mut Option<Result<RetainedCloneStep,E>>,call:impl for<'a,'r> FnOnce(&mut RetainedAllocationEffect<'a>,OriginalEffectReply<'r,RetainedCloneStep,E>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,E>,ValueError>,error_progress:impl FnOnce(&E)->RetainedCloneProgress){let ((poll,actual),heap)=observe(||bank.run(grant,work,|effect|{let before=effect.performed_work();let complete=call(effect,OriginalEffectReply::borrow(slot).unwrap()).unwrap();assert!(complete.is_recorded());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("closed vector leaf remained pending")};turn.result.unwrap();let progress=match slot.as_ref().unwrap(){Ok(step)=>step.progress(),Err(error)=>error_progress(error)};if let Some(actual)=actual{assert_eq!(actual,heap.0)}assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));let _=bank.take_admitted();bank.post(progress,grant,heap)}
fn clear_reply<E>(bank:&mut EffectBank,slot:&mut Option<Result<RetainedCloneStep,E>>){let bytes=std::mem::size_of::<Option<Result<RetainedCloneStep,E>>>();let grant=bank.loan(1,bytes);let ((poll,actual),heap)=observe(||bank.run(grant,1,|effect|{assert!(effect.performed(1).unwrap());drop(slot.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("reply header clear pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap(),grant,heap)}
fn clear_row(bank:&mut EffectBank,slot:&mut Option<u8>){let bytes=std::mem::size_of::<Option<u8>>();let grant=bank.loan(1,bytes);let ((poll,actual),heap)=observe(||bank.run(grant,1,|effect|{assert!(effect.performed(1).unwrap());*slot=None;RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("row header clear pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap(),grant,heap)}
#[test]fn actual_vector_borrowed_admission_and_rows_preserve_the_original_backing(){let law:serde_json::Value=serde_json::from_str(include_str!("borrowed.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let rows:Vec<u8>=law["rows"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as u8).collect();let pointer=rows.as_ptr();let bytes=rows.capacity()*std::mem::size_of::<u8>();let mut input=Some(rows);let mut owner=None;let mut reply=None;let demand=OriginalVectorCursor::<u8>::constructor_demand();assert!(demand.copy_bytes<=4096);let grant=bank.loan(1,demand.copy_bytes);let denied=RetainedCloneGrant{maximum_items:0,..grant};run(&mut bank,denied,1,&mut reply,|effect,reply|OriginalVectorCursor::admit_into(&mut input,&mut owner,effect,reply),ValueError::retained_progress);assert_eq!(reply.as_ref().unwrap().as_ref().unwrap().progress(),Default::default());assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(owner.is_none());clear_reply(&mut bank,&mut reply);run(&mut bank,grant,1,&mut reply,|effect,reply|OriginalVectorCursor::admit_into(&mut input,&mut owner,effect,reply),ValueError::retained_progress);assert!(input.is_none());assert_eq!(owner.as_ref().unwrap().remaining().as_ptr(),pointer);clear_reply(&mut bank,&mut reply);let mut row=Some(99u8);let demand=owner.as_ref().unwrap().next_take_demand();let grant=bank.loan(1,demand.copy_bytes);run(&mut bank,grant,1,&mut reply,|effect,reply|owner.as_mut().unwrap().take_front_into(&mut row,effect,reply),ValueError::retained_progress);assert!(reply.as_ref().unwrap().is_err());assert_eq!(row,Some(99));assert_eq!(owner.as_ref().unwrap().remaining().as_ptr(),pointer);clear_reply(&mut bank,&mut reply);clear_row(&mut bank,&mut row);for (index,value) in law["rows"].as_array().unwrap().iter().enumerate(){let demand=owner.as_ref().unwrap().next_take_demand();let grant=bank.loan(1,demand.copy_bytes);let denied=RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..grant};run(&mut bank,denied,1,&mut reply,|effect,reply|owner.as_mut().unwrap().take_front_into(&mut row,effect,reply),ValueError::retained_progress);assert!(row.is_none());assert_eq!(owner.as_ref().unwrap().remaining().as_ptr(),unsafe{pointer.add(index)});clear_reply(&mut bank,&mut reply);run(&mut bank,grant,1,&mut reply,|effect,reply|owner.as_mut().unwrap().take_front_into(&mut row,effect,reply),ValueError::retained_progress);assert_eq!(row,Some(value.as_u64().unwrap()as u8));clear_reply(&mut bank,&mut reply);clear_row(&mut bank,&mut row)}let demand=owner.as_ref().unwrap().begin_close_demand();let grant=bank.loan(1,demand.copy_bytes);run(&mut bank,grant,1,&mut reply,|effect,reply|owner.as_mut().unwrap().begin_close_into(effect,reply),ValueError::retained_progress);clear_reply(&mut bank,&mut reply);let demand=owner.as_ref().unwrap().next_demand(4096).unwrap();assert_eq!(demand.release_bytes,bytes);let grant=bank.loan(1,demand.copy_bytes);let mut close=None;let denied=RetainedCloneGrant{maximum_release_bytes:bytes-1,..grant};run(&mut bank,denied,1,&mut close,|effect,reply|owner.as_mut().unwrap().close_into(4096,effect,reply),OriginalRetirementFailure::retained_progress);assert_eq!(close.as_ref().unwrap().as_ref().unwrap().progress(),Default::default());assert_eq!(!owner.as_ref().unwrap().terminal_is_empty(),law["releaseDenialPreserves"].as_bool().unwrap());clear_reply(&mut bank,&mut close);run(&mut bank,grant,1,&mut close,|effect,reply|owner.as_mut().unwrap().close_into(4096,effect,reply),OriginalRetirementFailure::retained_progress);assert!(owner.as_ref().unwrap().terminal_is_empty());clear_reply(&mut bank,&mut close);let bytes=std::mem::size_of::<Option<OriginalVectorCursor<u8>>>();let grant=bank.loan(1,bytes);let ((poll,actual),heap)=observe(||bank.run(grant,1,|effect|{assert!(effect.performed(1).unwrap());drop(owner.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("cursor header clear pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap(),grant,heap);assert!(bank.is_idle());assert!(bank.into_wallet().is_ok())}

use semio_framework_value_retirement::retirement::{RetireOwned,RetirementCursor,RetirementStep};
static STARTS:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);static RECOVERS:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
struct Probe;struct ProbeCursor{phase:u8}
impl RetireOwned for Probe{type RetirementCursor=ProbeCursor;fn retirement_seed(self)->ProbeCursor{ProbeCursor{phase:0}}fn controlled_retirement_supported()->bool{true}}
impl RetirementCursor for ProbeCursor{fn next_demand(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(if self.phase==2{Default::default()}else{RetirementDemand{copy_bytes:std::mem::size_of::<u8>(),depth:1,..Default::default()}})}fn next_computational_work(&self,_:usize)->Result<u64,ValueError>{Ok(if self.phase==2{0}else{2})}fn terminal_is_empty(&self)->bool{self.phase==2}fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(std::mem::size_of::<Self>())}fn close_into<'r>(&mut self,_body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetirementStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetirementStep,OriginalRetirementFailure>,ValueError>{assert_eq!(self.phase,0);assert!(effect.performed(1)?);self.phase=1;STARTS.fetch_add(1,std::sync::atomic::Ordering::SeqCst);Ok(reply.pending())}fn recover_close_into<'r>(&mut self,_body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetirementStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetirementStep,OriginalRetirementFailure>,ValueError>{assert_eq!(self.phase,1);assert!(effect.performed(1)?);self.phase=2;RECOVERS.fetch_add(1,std::sync::atomic::Ordering::SeqCst);let _recorded=reply.complete(Ok(RetirementStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of::<u8>(),..Default::default()},1)));panic!("recorded vector child unwind")}}
struct Driver<'a>{owner:&'a mut semio_framework_value_original_vector::OriginalVectorRetirementSeed<Probe>}
impl OriginalEffectProducer for Driver<'_>{type Output=RetirementStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=()where 'b:'a;fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.owner.close_into(4096,effect,reply)}fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.owner.recover_close_into(4096,effect,reply)}}
fn erase_reply(bank:&mut EffectBank,slot:&mut Option<Result<RetirementStep,OriginalRetirementFailure>>){let bytes=std::mem::size_of::<Option<Result<RetirementStep,OriginalRetirementFailure>>>();let g=bank.loan(1,bytes);let ((poll,actual),heap)=observe(||bank.run(g,1,|effect|{assert!(effect.performed(1).unwrap());drop(slot.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("vector retirement reply header pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap(),g,heap)}
#[test]fn erased_vector_child_reply_survives_pending_and_unwind_without_replay(){let law:serde_json::Value=serde_json::from_str(include_str!("borrowed.json")).unwrap();STARTS.store(0,std::sync::atomic::Ordering::SeqCst);RECOVERS.store(0,std::sync::atomic::Ordering::SeqCst);let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut input=Some(vec![Probe]);let mut cursor=None;let d=OriginalVectorCursor::<Probe>::constructor_demand();let g=bank.loan(1,d.copy_bytes);let mut reply=None;run(&mut bank,g,1,&mut reply,|effect,reply|OriginalVectorCursor::admit_into(&mut input,&mut cursor,effect,reply),ValueError::retained_progress);clear_reply(&mut bank,&mut reply);let bytes=std::mem::size_of::<Option<OriginalVectorCursor<Probe>>>()+std::mem::size_of::<Option<semio_framework_value_original_vector::OriginalVectorRetirementSeed<Probe>>>();assert!(bytes<=4096);let g=bank.loan(1,bytes);let mut seed=None;let ((poll,actual),heap)=observe(||bank.run(g,1,|effect|{assert!(effect.performed(1).unwrap());seed=Some(cursor.take().unwrap().retirement_seed());RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("vector seed pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap(),g,heap);let mut authority=Some(OriginalEffectAuthority::new(Driver{owner:seed.as_mut().unwrap()}));let mut action=None;let mut output=None;let mut interrupted=false;for _ in 0..law["maximumTurns"].as_u64().unwrap(){if authority.as_ref().unwrap().producer().owner.terminal_is_empty(){break}let d=authority.as_ref().unwrap().producer().owner.next_demand(4096).unwrap();let units=authority.as_ref().unwrap().producer().owner.next_computational_work(4096).unwrap();assert!(d.copy_bytes<=4096);let g=bank.loan(1,d.copy_bytes);let mut heap_sum=(0usize,0usize);for _ in 0..law["maximumTurns"].as_u64().unwrap(){let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||observe(||bank.run(g,units,|effect|{let before=effect.performed_work();let ready=authority.as_mut().unwrap().drive(&mut (),effect,&mut action).unwrap();let work=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work})}else{RetainedWorkPoll::Pending{work}}}))));let ((poll,actual),heap)=match result{Ok(result)=>result,Err(payload)=>{if interrupted||RECOVERS.load(std::sync::atomic::Ordering::SeqCst)!=1{std::panic::resume_unwind(payload)}interrupted=true;continue}};heap_sum.0+=heap.0;heap_sum.1+=heap.1;if matches!(&poll,RetainedWorkPoll::Pending{..})&&STARTS.load(std::sync::atomic::Ordering::SeqCst)>0{assert_eq!(law["selectedBodyImmutable"],true);assert!(authority.as_ref().unwrap().producer().owner.next_demand(4095).is_err());assert!(authority.as_ref().unwrap().producer().owner.next_computational_work(4095).is_err());}if let Some(actual)=actual{assert_eq!(actual,heap_sum.0)}if let RetainedWorkPoll::Complete(turn)=poll{turn.result.unwrap();let p=match action.as_ref().unwrap().recorded_reply().unwrap(){Ok(RetirementStep::Progress(p,_))=>*p,Ok(RetirementStep::Complete(_))=>Default::default(),Err(error)=>error.retained_progress(),_=>panic!("unexpected vector retirement reply")};let _=bank.take_admitted();bank.post(p,g,heap_sum);break}}assert!(action.as_ref().unwrap().recorded_reply().is_some());let d=OriginalEffectAuthority::<Driver<'_>>::transfer_reply_demand().unwrap();assert!(d.copy_bytes<=4096);let g=bank.loan(1,d.copy_bytes);let ((poll,actual),heap)=observe(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(authority.as_mut().unwrap().transfer_reply_into(&(),&mut action,&mut output,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("vector reply transfer pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap().unwrap(),g,heap);assert!(output.as_ref().unwrap().is_ok());erase_reply(&mut bank,&mut output)}assert!(authority.as_ref().unwrap().producer().owner.terminal_is_empty());assert_eq!(STARTS.load(std::sync::atomic::Ordering::SeqCst),law["childCalls"].as_u64().unwrap()as usize);assert_eq!(RECOVERS.load(std::sync::atomic::Ordering::SeqCst),law["childRecovers"].as_u64().unwrap()as usize);let d=OriginalEffectAuthority::<Driver<'_>>::producer_transfer_demand().unwrap();let g=bank.loan(1,d.copy_bytes);let mut producer=None;let ((poll,actual),heap)=observe(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&(),&mut producer,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("vector driver transfer pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap().unwrap(),g,heap);let bytes=std::mem::size_of::<Option<Driver<'_>>>();let g=bank.loan(1,bytes);let ((poll,actual),heap)=observe(||bank.run(g,1,|effect|{assert!(effect.performed(1).unwrap());drop(producer.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("driver header pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap(),g,heap);drop(producer);drop(authority);let bytes=std::mem::size_of::<Option<semio_framework_value_original_vector::OriginalVectorRetirementSeed<Probe>>>();let g=bank.loan(1,bytes);let ((poll,actual),heap)=observe(||bank.run(g,1,|effect|{assert!(effect.performed(1).unwrap());drop(seed.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<RetainedCloneProgress,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("vector seed header pending")};assert_eq!(actual,None);let _=bank.take_admitted();bank.post(turn.result.unwrap(),g,heap);assert!(bank.into_wallet().is_ok())}
